import { useState, useRef, useEffect } from "react";

export default function App() {
  const [open, setOpen] = useState(false);
  const closeRef = useRef(null);
  useEffect(() => { if (open) closeRef.current?.focus(); }, [open]);   // chuyển focus vào hộp thoại

  return (
    <main>
      <h1>Cửa hàng</h1>
      {/* label gắn với input bằng htmlFor/id: bấm nhãn thì focus ô nhập, trình đọc màn hình đọc nhãn */}
      <label htmlFor="email">Email</label>
      <input id="email" type="email" autoComplete="email" />

      {/* dùng <button>, không phải <div onClick>: có sẵn bàn phím, focus, vai trò */}
      <button id="open" onClick={() => setOpen(true)}>Mở hộp thoại</button>

      {open && (
        <div role="dialog" aria-modal="true" aria-labelledby="t" onKeyDown={(e) => e.key === "Escape" && setOpen(false)}>
          <h2 id="t">Xác nhận</h2>
          <button id="close" ref={closeRef} onClick={() => setOpen(false)}>Đóng</button>
        </div>
      )}
    </main>
  );
}

